# and is not trivially small (to keep difficulty). We attempt randomized choices and search.

def count_b(b, delta):
    # Count all two-digit base-b numbers n with leading digit x>=1, 0<=y<=b-1,
    # such that x+y = s is an integer and s^2 = n + delta.
    # Derivation: s^2 - s - delta = x(b-1), y = s - x.
    total = 0
    den = b - 1
    # s is sum of two base-b digits, with x in [1, b-1], y in [0, b-1], so s in [1, 2(b-1)].
    for s in range(1, 2*den + 1):
        num = s*s - s - delta
        if num % den != 0:
            continue
        x = num // den
        if x < 1 or x > den:
            continue
        y = s - x
        if y < 0 or y > den:
            continue
        # Verify relationship explicitly
        n = x*b + y
        if s*s == n + delta:
            total += 1
    return total

# Try randomized parameters until a valid nontrivial instance is found
for _ in range(200):
    delta = rng.randint(1, 400)
    threshold = rng.randint(12, 24)
    b_max = 3000
    answer_b = None
    for b in range(2, b_max + 1):
        c = count_b(b, delta)
        if c > threshold:
            answer_b = b
            break
    if answer_b is None:
        continue
    # Enforce nontriviality: avoid tiny bases which make the search trivial
    if answer_b < 120:
        # Try again with different parameters to push minimal b higher
        continue
    return {'delta': delta, 'threshold': threshold}

# Fallback in case randomized attempts did not succeed within limits
# Choose a slightly harder-than-seed threshold with delta = 0 (still valid augmentation)
return {'delta': 0, 'threshold': 11}

